//! Independent literal replay of the 257 distributed H18PIV2 K22 samples.
mod referee {
include!("../unaudited-codex-orbit0-hidden-k16-children-prefix-2026-08-23/run_hidden_children_prefix.rs");
const INPUT:&str="computations/unaudited-codex-orbit0-hidden-k16-k2-full-orbit-2026-08-23/checkpoint_k18_22_pivotable.bin";
const TSV:&str="computations/unaudited-codex-orbit0-k22-hidden-collected-k18-2026-08-24/results_k22_hidden_collected_k18.json.samples.tsv";
const OUT:&str="computations/unaudited-codex-orbit0-k22-hidden-collected-k18-2026-08-24/results_k22_hidden_samples_referee.json";
const N:u64=158_439_965;
fn hex(row:&Row)->String{row.0.iter().map(|x|format!("{:02x}",x)).collect()}
pub fn run(){let begun=Instant::now();let e=parse();let c=cenv();let mut f=File::open(INPUT).unwrap();let raw=std::fs::read_to_string(TSV).unwrap();let mut lines=raw.lines();assert_eq!(lines.next().unwrap(),"input_index\trow\twitness_pair\tweight_w2\tm2\tm3\tselected_p3\tR224_children\tR224_charge_scaled_U\tpivotable_K20\tselected_p4\tR2222_children\tR2222_charge_scaled_U");let(mut rows,mut a_children,mut b_children,mut a_charge,mut b_charge)=(0u64,0u64,0u64,0i128,0i128);for line in lines{let x:Vec<_>=line.split('\t').collect();assert_eq!(x.len(),13);let idx=x[0].parse::<u64>().unwrap();assert_eq!(idx,rows*(N-1)/256);f.seek(SeekFrom::Start(80+80*idx)).unwrap();let mut rec=[0u8;80];f.read_exact(&mut rec).unwrap();assert_eq!(rec[78],1);let mut rr=[0;24];rr.copy_from_slice(&rec[..24]);let row=Row(rr);let mut ww=[0;24];ww.copy_from_slice(&rec[40..64]);assert_eq!(hex(&row),x[1]);assert_eq!(hex(&Row(ww)),x[2]);let w=i128::from_le_bytes(rec[24..40].try_into().unwrap());assert_eq!(w,x[3].parse().unwrap());let m2=rec[79]as usize;assert_eq!(m2,x[4].parse().unwrap());let s=signature(&row.0,&e);assert_eq!(s.iter().map(|&z|z as usize).sum::<usize>(),6);let ps3=available(s,&e);let m3=ps3.len();assert_eq!(m3,x[5].parse().unwrap());assert_eq!(m3,x[6].parse().unwrap());assert_eq!(w%(m3 as i128),0);assert_eq!(U%((m2*m3)as i128),0);let wa=-w/(m3 as i128);let(mut ac,mut aq,mut mid,mut p4n,mut bc,mut bq)=(0u64,0i128,0u64,0u64,0u64,0i128);for p3 in ps3{for t in &c.k4[p3]{let child=replace_anchor(&row,&e.anchors[p3],t);let z=signature(&child.0,&e);assert_eq!(z.iter().map(|&v|v as usize).sum::<usize>(),2);assert!(available(z,&e).is_empty());aq+=wa*(*c.dual.get(&literal_ckey(&child,&c)).unwrap_or(&0)as i128);ac+=1}for t in &e.all_k2[p3]{let row20=replace_anchor(&row,&e.anchors[p3],t);let s20=signature(&row20.0,&e);assert_eq!(s20.iter().map(|&v|v as usize).sum::<usize>(),4);let ps4=available(s20,&e);if ps4.is_empty(){continue}assert_eq!(ps4.len(),1);mid+=1;let wb=w/((m3*ps4.len())as i128);for p4 in ps4{p4n+=1;for u in &e.all_k2[p4]{let child=replace_anchor(&row20,&e.anchors[p4],u);let z=signature(&child.0,&e);assert_eq!(z.iter().map(|&v|v as usize).sum::<usize>(),2);assert!(available(z,&e).is_empty());bq+=wb*(*c.dual.get(&literal_ckey(&child,&c)).unwrap_or(&0)as i128);bc+=1}}}}assert_eq!(ac,x[7].parse().unwrap());assert_eq!(aq,x[8].parse().unwrap());assert_eq!(mid,x[9].parse().unwrap());assert_eq!(p4n,x[10].parse().unwrap());assert_eq!(bc,x[11].parse().unwrap());assert_eq!(bq,x[12].parse().unwrap());rows+=1;a_children+=ac;b_children+=bc;a_charge+=aq;b_charge+=bq}assert_eq!(rows,257);let out=format!("{{\n  \"status\":\"PASS_INDEPENDENT_257_LITERAL_H18PIV2_TWO_SINK_K22_REFEREE\",\n  \"strict_ids\":[\"D14:222|R:2-2-4\",\"D14:222|R:2-2-2-2\"],\n  \"distributed_parents\":{},\n  \"first_index\":0,\n  \"last_index\":{},\n  \"literal_R224_terminal_children\":{},\n  \"literal_R2222_terminal_children\":{},\n  \"sample_R224_charge_scaled_U\":\"{}\",\n  \"sample_R2222_charge_scaled_U\":\"{}\",\n  \"all_divisions_exact\":true,\n  \"all_K22_children_terminal\":true,\n  \"elapsed_seconds\":{:.6},\n  \"scope\":\"257 distributed literal parents only; no full rerun, parent rows, K23, or K24\"\n}}\n",rows,N-1,a_children,b_children,a_charge,b_charge,begun.elapsed().as_secs_f64());std::fs::write(OUT,&out).unwrap();print!("{}",out)}
}
fn main(){referee::run()}
